actions.script:
let errors = null
// queued on a worker (wait false): the page follows the job
ec.service.sync().name('org.moqui.dev.DatabaseServices.run#DatabaseJob').parameters({jobId: String(jobId || ''), wait: false}).call()
if (ec.message.hasError()) { errors = ec.message.errorsString; ec.message.clearErrors() }
ec.web.sendJsonResponse({errors})

const name = String(context.signal) == 'terminate' ? 'terminate#DatabaseSession' : 'cancel#DatabaseSession'
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.' + name).parameters({db: context.db || null,
    pid: Number(context.pid), force: String(context.force) == 'true'}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))
